    public string TrustLevel { get; set; } = default!;
    public string TrustMessage { get; set; } = default!;
    public string SenderDomain { get; set; } = default!;

    internal void Write(BeWriter w)
    {
        Codec.WriteString(w, EmailId);
        Codec.WriteOptionalString(w, Html);
        Codec.WriteOptionalString(w, Text);
        Codec.WriteBool(w, RemoteImagesAllowed);
        Codec.WriteU32(w, BlockedCount);
        Codec.WriteSequence(w, BlockedUrls, (bw, x) => { Codec.WriteString(bw, x); });
        Codec.WriteU32(w, RemovedTagCount);
        Codec.WriteBool(w, Truncated);
        Codec.WriteString(w, TrustLevel);
        Codec.WriteString(w, TrustMessage);
        Codec.WriteString(w, SenderDomain);
    }

    internal static RenderedBodyDto Read(BeReader r)
    {
        return new RenderedBodyDto
        {
            EmailId = Codec.ReadString(r),
            Html = Codec.ReadOptionalString(r),
            Text = Codec.ReadOptionalString(r),
            RemoteImagesAllowed = Codec.ReadBool(r),
            BlockedCount = Codec.ReadU32(r),
            BlockedUrls = Codec.ReadSequence(r, br => Codec.ReadString(br)),
            RemovedTagCount = Codec.ReadU32(r),
            Truncated = Codec.ReadBool(r),
            TrustLevel = Codec.ReadString(r),
            TrustMessage = Codec.ReadString(r),
            SenderDomain = Codec.ReadString(r),
        };
    }
}

