public sealed class PushEventDto
{
    public PushEventKindDto Kind { get; set; } = default!;
    public string Reason { get; set; } = default!;
    public ulong Inserted { get; set; } = default!;
    public ulong Updated { get; set; } = default!;
    public ulong Deleted { get; set; } = default!;
    public ulong Unchanged { get; set; } = default!;
    public ulong UnreadTotal { get; set; } = default!;
    public IReadOnlyList<MailboxUnreadDto> UnreadByMailbox { get; set; } = default!;
    public ulong Coalesced { get; set; } = default!;
    public string Error { get; set; } = default!;
    public ulong? RetryInMs { get; set; } = default!;

    internal void Write(BeWriter w)
    {
        Codec.WriteEnum(w, (int)Kind);
        Codec.WriteString(w, Reason);
        Codec.WriteU64(w, Inserted);
        Codec.WriteU64(w, Updated);
        Codec.WriteU64(w, Deleted);
        Codec.WriteU64(w, Unchanged);
        Codec.WriteU64(w, UnreadTotal);
        Codec.WriteSequence(w, UnreadByMailbox, (bw, x) => { x.Write(bw); });
        Codec.WriteU64(w, Coalesced);
        Codec.WriteString(w, Error);
        Codec.WriteOptionalU64(w, RetryInMs);
    }

    internal static PushEventDto Read(BeReader r)
    {
        return new PushEventDto
        {
            Kind = (PushEventKindDto)Codec.ReadEnum(r),
            Reason = Codec.ReadString(r),
            Inserted = Codec.ReadU64(r),
            Updated = Codec.ReadU64(r),
            Deleted = Codec.ReadU64(r),
            Unchanged = Codec.ReadU64(r),
            UnreadTotal = Codec.ReadU64(r),
            UnreadByMailbox = Codec.ReadSequence(r, br => global::CrossMail.Bindings.MailboxUnreadDto.Read(br)),
            Coalesced = Codec.ReadU64(r),
            Error = Codec.ReadString(r),
            RetryInMs = Codec.ReadOptionalU64(r),
        };
    }
}

